begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
select extensions.has_table('public', 'reader_clippings', 'private clippings table exists');
select extensions.ok(not pg_catalog.has_table_privilege('anon', 'public.reader_clippings', 'select'), 'anonymous users cannot read clippings');
select extensions.ok(not pg_catalog.has_table_privilege('authenticated', 'public.reader_clippings', 'insert'), 'writes require owner-checked RPC');
set local session_replication_role = replica;
insert into auth.users(id) values ('10000000-0000-0000-0000-000000000001'), ('10000000-0000-0000-0000-000000000002');
set local session_replication_role = origin;
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000001', true);
select extensions.lives_ok($$select public.save_reader_clipping('10000000-0000-0000-0000-000000000001', null, 'book', 'demo:one', '示例书', 'chapter-1', '第一章', '/book/demo/one?chapter=chapter-1', '原文', '笔记', '*')$$, 'reader saves a clipping');
select set_config('test.clip_id', (select id::text from public.reader_clippings limit 1), true);
set local role authenticated;
select extensions.is((select count(*)::integer from public.reader_clippings), 1, 'RLS lets the owner read');
select extensions.is(jsonb_array_length(public.get_reader_clippings('10000000-0000-0000-0000-000000000001')), 1, 'owner sees saved clipping');
select extensions.is(public.get_reader_clipping_collections('10000000-0000-0000-0000-000000000001'), '["*"]'::jsonb, 'literal special characters in topic names are preserved');
select extensions.is(jsonb_array_length(public.get_reader_clippings('10000000-0000-0000-0000-000000000001', '原文', '*')), 1, 'search and topic filter find the clipping');
select extensions.is(jsonb_array_length(public.get_reader_clippings('10000000-0000-0000-0000-000000000001', '不存在')), 0, 'search does not return unrelated clippings');
select extensions.throws_ok($$select public.get_reader_clippings('10000000-0000-0000-0000-000000000002')$$, 'P0001', 'Authentication required', 'mismatched account guard fails');
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000002', true);
select extensions.is(jsonb_array_length(public.get_reader_clippings('10000000-0000-0000-0000-000000000002')), 0, 'another reader cannot list clippings');
select extensions.throws_ok($$select public.save_reader_clipping('10000000-0000-0000-0000-000000000002', current_setting('test.clip_id')::uuid, 'book', 'demo:one', '示例书', 'chapter-1', '第一章', '/book/demo/one', 'changed', '', '')$$, 'P0001', 'Clipping not found', 'another reader cannot edit a known clipping');
select public.delete_reader_clipping('10000000-0000-0000-0000-000000000002', current_setting('test.clip_id')::uuid);
select extensions.is((select count(*)::integer from public.reader_clippings), 0, 'RLS hides another reader clipping');
reset role;
select extensions.is((select count(*)::integer from public.reader_clippings), 1, 'another reader cannot delete a known clipping');
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000001', true);
select public.delete_reader_clipping('10000000-0000-0000-0000-000000000001', current_setting('test.clip_id')::uuid);
select extensions.is(jsonb_array_length(public.get_reader_clippings('10000000-0000-0000-0000-000000000001')), 0, 'owner can delete their clipping');
select * from extensions.finish();
rollback;
